import {recordAssetSale} from './shift-finance.mjs?v=chair-shortcut-31';
export const FIXTURES={'jar-0':{name:'Bean jar',price:20},'jar-1':{name:'Bean jar',price:20},'jar-2':{name:'Bean jar',price:20},cups:{name:'Cup stack',price:20},napkins:{name:'Napkin holder',price:15},fridge:{name:'Fridge',price:220},storage:{name:'Storage shelf',price:120},sign:{name:'Study sign',price:45},'menu-0':{name:'Coffee menu',price:40},'menu-1':{name:'Bakery menu',price:40},'menu-2':{name:'Specials menu',price:40},door:{name:'Entrance door',price:160},espresso:{name:'Espresso machine',price:300},grinder:{name:'Grinder',price:130},pastry:{name:'Pastry display',price:180},till:{name:'Register',price:100},'counter-plant':{name:'Counter plant',price:25},'nook-plant':{name:'Nook plant',price:35},'nook-rug':{name:'Nook rug',price:45},'extra-window':{name:'Added window',price:450},'nook-window':{name:'Nook window',price:125},bathroom:{name:'Bathroom',price:450},nook:{name:'Study nook',price:1350},'terrace-0':{name:'Planter',price:40},'terrace-1':{name:'Planter',price:40},'terrace-2':{name:'Planter',price:40},'terrace-3':{name:'Planter',price:40}};
export function fixtureSalePrice(key){return Math.floor((FIXTURES[key]?.price||0)*.6);}
export function sellFixture(s,key){if(!FIXTURES[key]||s.soldFixtures?.includes(key))return false;s.soldFixtures||=[];s.soldFixtures.push(key);recordAssetSale(s,fixtureSalePrice(key));if(key==='bathroom'){s.renovations.bathroom=false;s.renovations.bathrooms=false;}if(key==='nook')s.renovations.nook=false;if(key==='extra-window')s.renovations.window=false;return true;}
export function buyFixture(s,key){const item=FIXTURES[key];if(!item||!s.soldFixtures?.includes(key)||s.money<item.price)return false;s.money-=item.price;s.soldFixtures=s.soldFixtures.filter(k=>k!==key);if(key==='bathroom')s.renovations.bathroom=true;if(key==='nook'){s.renovations.nook=true;if(!s.objects.some(o=>o.type==='nookArea'))s.objects.push({id:'nook-area',type:'nookArea',x:9,z:.7,r:0,upgraded:true});}if(key==='extra-window')s.renovations.window=true;return true;}
